1	/**
2	 * `bech32.convertbits`: regroup a sequence of integers from `frombits`-wide
3	 * units into `tobits`-wide units, optionally zero padding the tail.
4	 *
5	 * Behaviour reproduced from the library's observable interface, including the
6	 * three ways it can fail:
7	 *   * a value outside `[0, 2**frombits)`         -> returns None
8	 *   * a negative bit width                       -> ValueError: negative shift count
9	 *   * a None input (a previous call's failure)   -> TypeError: not iterable
10	 * The line numbers below are the ones the library reports in a traceback.
11	 */
12	
13	import { leftShift, rightShift } from '../python/bitops.mjs';
14	import { PyTypeError, frame, inFrame, withFrame } from '../python/errors.mjs';
15	
16	const MODULE_FILE = 'bech32/__init__.py';
17	
18	/** Source lines of `convertbits` that can raise. */
19	const LINE = {
20	  maxValue: 88, // maxv = (1 << tobits) - 1
21	  maxAccumulator: 89, // max_acc = (1 << (frombits + tobits - 1)) - 1
22	  iteration: 90, // for value in data:
23	  rangeCheck: 91, // if value < 0 or (value >> frombits):
24	};
25	
26	function libraryFrame(line) {
27	  return frame({ file: MODULE_FILE, line, func: 'convertbits' });
28	}
29	
30	/**
31	 * @param {bigint[]|null} data
32	 * @param {bigint} frombits
33	 * @param {bigint} tobits
34	 * @param {boolean} [pad]
35	 * @returns {bigint[]|null}
36	 */
37	export function convertbits(data, frombits, tobits, pad = true) {
38	  let acc = 0n;
39	  let bits = 0n;
40	  const ret = [];
41	  const maxValue = inFrame(libraryFrame(LINE.maxValue), () => leftShift(1n, tobits) - 1n);
42	  const maxAccumulator = inFrame(
43	    libraryFrame(LINE.maxAccumulator),
44	    () => leftShift(1n, frombits + tobits - 1n) - 1n,
45	  );
46	
47	  if (data === null || data === undefined) {
48	    throw withFrame(
49	      new PyTypeError("'NoneType' object is not iterable"),
50	      libraryFrame(LINE.iteration),
51	    );
52	  }
53	
54	  for (const value of data) {
55	    const outOfRange = inFrame(
56	      libraryFrame(LINE.rangeCheck),
57	      () => value < 0n || rightShift(value, frombits) !== 0n,
58	    );
59	    if (outOfRange) return null;
60	    acc = ((acc << frombits) | value) & maxAccumulator;
61	    bits += frombits;
62	    while (bits >= tobits) {
63	      bits -= tobits;
64	      ret.push(rightShift(acc, bits) & maxValue);
65	    }
66	  }
67	
68	  if (pad) {
69	    if (bits !== 0n) ret.push(leftShift(acc, tobits - bits) & maxValue);
70	  } else if (bits >= frombits || (leftShift(acc, tobits - bits) & maxValue) !== 0n) {
71	    return null;
72	  }
73	  return ret;
74	}
