1	/**
2	 * Arbitrary-precision shift/mask helpers that raise the same errors CPython
3	 * raises for `int` operands.
4	 */
5	
6	import { PyMemoryError, PyValueError } from './errors.mjs';
7	
8	function guardHuge(operation) {
9	  try {
10	    return operation();
11	  } catch (error) {
12	    // An allocation CPython would also refuse: it reports MemoryError.
13	    if (error instanceof RangeError) throw new PyMemoryError();
14	    throw error;
15	  }
16	}
17	
18	/** `value << count`, raising `ValueError: negative shift count`. */
19	export function leftShift(value, count) {
20	  if (count < 0n) throw new PyValueError('negative shift count');
21	  return guardHuge(() => value << count);
22	}
23	
24	/** `value >> count`, raising `ValueError: negative shift count`. */
25	export function rightShift(value, count) {
26	  if (count < 0n) throw new PyValueError('negative shift count');
27	  return guardHuge(() => value >> count);
28	}
