1	/**
2	 * The slice of `argparse.ArgumentParser` this program relies on: long options
3	 * that each take one value, `-h/--help`, prefix matching, `--opt=value`, and
4	 * argparse's exact error reporting (usage on stderr, status 2).
5	 */
6	
7	import { SystemExit } from '../python/errors.mjs';
8	import { PyException } from '../python/errors.mjs';
9	import { reprString } from '../python/repr.mjs';
10	import { writeStderr, writeStdout } from '../python/io.mjs';
11	import { HelpFormatter } from './formatter.mjs';
12	import { strType } from './types.mjs';
13	
14	/** `argparse._negative_number_matcher`; `\d` spans all Unicode digits. */
15	const NEGATIVE_NUMBER = /^-\p{Nd}+$|^-\p{Nd}*\.\p{Nd}+$/u;
16	
17	const PREFIX_CHARS = '-';
18	
19	class Action {
20	  constructor({ optionStrings, dest, type, required, help, metavar, isHelp }) {
21	    this.optionStrings = optionStrings;
22	    this.dest = dest;
23	    this.type = type;
24	    this.required = required;
25	    this.help = help;
26	    this.metavar = metavar;
27	    this.isHelp = isHelp;
28	    this.takesValue = !isHelp;
29	  }
30	
31	  /** `argparse._get_action_name`: how the action is named in error messages. */
32	  get name() {
33	    return this.optionStrings.join('/');
34	  }
35	}
36	
37	/** Raised by value conversion, reported by the parser as an exit-2 error. */
38	class ArgumentError extends Error {
39	  constructor(action, message) {
40	    super(`argument ${action.name}: ${message}`);
41	    this.argparseMessage = `argument ${action.name}: ${message}`;
42	  }
43	}
44	
45	export class ArgumentParser {
46	  constructor({ prog }) {
47	    this.prog = prog;
48	    this.actions = [];
49	    this.optionStringActions = new Map();
50	    this.add_argument(['-h', '--help'], {
51	      action: 'help',
52	      help: 'show this help message and exit',
53	    });
54	  }
55	
56	  /**
57	   * @param {string|string[]} flags   e.g. `'--a'`
58	   * @param {object} options          `type`, `required`, `help`, `metavar`, `action`
59	   */
60	  add_argument(flags, options = {}) {
61	    const optionStrings = Array.isArray(flags) ? flags : [flags];
62	    const longest = optionStrings.find((flag) => flag.startsWith('--')) ?? optionStrings[0];
63	    const dest = longest.replace(/^-+/, '').replace(/-/g, '_');
64	    const isHelp = options.action === 'help';
65	    const action = new Action({
66	      optionStrings,
67	      dest,
68	      type: options.type ?? strType,
69	      required: options.required ?? false,
70	      help: options.help ?? null,
71	      metavar: options.metavar ?? dest.toUpperCase(),
72	      isHelp,
73	    });
74	    this.actions.push(action);
75	    for (const optionString of optionStrings) this.optionStringActions.set(optionString, action);
76	    return action;
77	  }
78	
79	  get formatter() {
80	    return new HelpFormatter(this.prog);
81	  }
82	
83	  format_usage() {
84	    return this.#normalise(this.formatter.formatUsage(this.actions));
85	  }
86	
87	  format_help() {
88	    return this.formatter.formatHelp(this.actions);
89	  }
90	
91	  /** `HelpFormatter.format_help`'s trailing-newline normalisation. */
92	  #normalise(text) {
93	    return `${text.replace(/\n\n\n+/g, '\n\n').replace(/^\n+|\n+$/g, '')}\n`;
94	  }
95	
96	  print_usage(stream = writeStdout) {
97	    stream(this.format_usage());
98	  }
99	
100	  print_help(stream = writeStdout) {
101	    stream(this.format_help());
102	  }
103	
104	  /** `parser.exit`: optionally print a message, then raise `SystemExit`. */
105	  exit(status = 0, message = null) {
106	    if (message) writeStderr(message);
107	    throw new SystemExit(status);
108	  }
109	
110	  /** `parser.error`: usage plus `prog: error: message` on stderr, status 2. */
111	  error(message) {
112	    this.print_usage(writeStderr);
113	    this.exit(2, `${this.prog}: error: ${message}\n`);
114	  }
115	
116	  /**
117	   * `_parse_optional`: decide whether a token is an option, a plain value, or
118	   * an option this parser does not know.
119	   */
120	  #classify(token) {
121	    if (token === '') return { kind: 'value' };
122	    if (!PREFIX_CHARS.includes(token[0])) return { kind: 'value' };
123	    if (this.optionStringActions.has(token)) {
124	      return { kind: 'option', action: this.optionStringActions.get(token), explicitArg: null };
125	    }
126	    if (Array.from(token).length === 1) return { kind: 'value' };
127	    if (token.includes('=')) {
128	      const separator = token.indexOf('=');
129	      const optionString = token.slice(0, separator);
130	      if (this.optionStringActions.has(optionString)) {
131	        return {
132	          kind: 'option',
133	          action: this.optionStringActions.get(optionString),
134	          explicitArg: token.slice(separator + 1),
135	        };
136	      }
137	    }
138	    const matches = this.#optionTuples(token);
139	    if (matches.length > 1) {
140	      const options = matches.map((match) => match.optionString).join(', ');
141	      this.error(`ambiguous option: ${token} could match ${options}`);
142	    }
143	    if (matches.length === 1) return { kind: 'option', ...matches[0] };
144	    if (NEGATIVE_NUMBER.test(token)) return { kind: 'value' };
145	    if (token.includes(' ')) return { kind: 'value' };
146	    return { kind: 'unknown' };
147	  }
148	
149	  /** `_get_option_tuples`: abbreviations, plus `-oVALUE` style short options. */
150	  #optionTuples(token) {
151	    const result = [];
152	    const separator = token.indexOf('=');
153	    if (token.startsWith('--')) {
154	      const optionPrefix = separator >= 0 ? token.slice(0, separator) : token;
155	      const explicitArg = separator >= 0 ? token.slice(separator + 1) : null;
156	      for (const [optionString, action] of this.optionStringActions) {
157	        if (optionString.startsWith(optionPrefix)) result.push({ action, optionString, explicitArg });
158	      }
159	      return result;
160	    }
161	    // Single dash: either an abbreviation or a value glued to a short option.
162	    const shortOptionPrefix = token.slice(0, 2);
163	    const shortExplicitArg = token.slice(2);
164	    for (const [optionString, action] of this.optionStringActions) {
165	      if (optionString === shortOptionPrefix) {
166	        result.push({ action, optionString, explicitArg: shortExplicitArg });
167	      } else if (optionString.startsWith(token)) {
168	        result.push({ action, optionString, explicitArg: null });
169	      }
170	    }
171	    return result;
172	  }
173	
174	  /** `_get_value`: apply `type`, turning failures into an ArgumentError. */
175	  #convert(action, text) {
176	    try {
177	      return action.type(text);
178	    } catch (error) {
179	      if (error instanceof PyException) {
180	        throw new ArgumentError(action, `invalid ${action.type.typeName} value: ${reprString(text)}`);
181	      }
182	      throw error;
183	    }
184	  }
185	
186	  #takeAction(action, namespace, value) {
187	    if (action.isHelp) {
188	      this.print_help(writeStdout);
189	      this.exit(0);
190	    }
191	    namespace[action.dest] = this.#convert(action, value);
192	  }
193	
194	  /** `parse_known_args`: the namespace plus every token left unclaimed. */
195	  parse_known_args(argv) {
196	    const namespace = {};
197	    for (const action of this.actions) {
198	      if (!action.isHelp) namespace[action.dest] = null;
199	    }
200	    const seen = new Set();
201	    const extras = [];
202	    let separatorSeen = false;
203	    let index = 0;
204	
205	    try {
206	      while (index < argv.length) {
207	        const token = argv[index];
208	        if (separatorSeen) {
209	          extras.push(token);
210	          index += 1;
211	          continue;
212	        }
213	        if (token === '--') {
214	          // The first `--` both ends option parsing and, with no positionals
215	          // declared, stays behind as an unrecognised argument.
216	          separatorSeen = true;
217	          extras.push(token);
218	          index += 1;
219	          continue;
220	        }
221	
222	        const classified = this.#classify(token);
223	        if (classified.kind !== 'option') {
224	          extras.push(token);
225	          index += 1;
226	          continue;
227	        }
228	
229	        const { action, explicitArg } = classified;
230	        seen.add(action);
231	        if (explicitArg !== null && explicitArg !== undefined) {
232	          if (!action.takesValue) {
233	            this.error(`argument ${action.name}: ignored explicit argument ${reprString(explicitArg)}`);
234	          }
235	          this.#takeAction(action, namespace, explicitArg);
236	          index += 1;
237	          continue;
238	        }
239	        if (!action.takesValue) {
240	          this.#takeAction(action, namespace, null);
241	          index += 1;
242	          continue;
243	        }
244	
245	        const next = index + 1 < argv.length ? argv[index + 1] : null;
246	        const nextIsValue =
247	          next !== null && next !== '--' && this.#classify(next).kind === 'value';
248	        if (!nextIsValue) {
249	          this.error(`argument ${action.name}: expected one argument`);
250	        }
251	        this.#takeAction(action, namespace, next);
252	        index += 2;
253	      }
254	    } catch (error) {
255	      if (error instanceof ArgumentError) this.error(error.argparseMessage);
256	      throw error;
257	    }
258	
259	    const missing = this.actions
260	      .filter((action) => action.required && !seen.has(action))
261	      .map((action) => action.name);
262	    if (missing.length > 0) {
263	      this.error(`the following arguments are required: ${missing.join(', ')}`);
264	    }
265	
266	    return [namespace, extras];
267	  }
268	
269	  parse_args(argv) {
270	    const [namespace, extras] = this.parse_known_args(argv);
271	    if (extras.length > 0) {
272	      this.error(`unrecognized arguments: ${extras.join(' ')}`);
273	    }
274	    return namespace;
275	  }
276	}
